const benefitTrend = computed(() => {
  const rows = (stats.benefit?.trendList ?? []).filter(t => t).map(t => ({
    month: String(t?.month ?? '').match(/-(\d{1,2})$/)?.[1] ? `${Number(String(t.month).match(/-(\d{1,2})$/)![1])}月` : String(t?.month ?? ''),
    org: num(t?.orgNum) ?? 0,
    acc: num(t?.accountNum) ?? 0,
    agr: num(t?.agreementNum) ?? 0,
    fund: num(t?.fundAmount) ?? 0,
  }))
  if (!rows.length) return null
  const maxBar = Math.max(1, ...rows.flatMap(r => [r.org, r.acc, r.agr]))
  const maxLine = Math.max(1, ...rows.map(r => r.fund))
  const W = 320, H = 150, left = 34, right = 10, top = 12, bottom = 34
  const plotW = W - left - right, plotH = H - top - bottom
  const step = plotW / rows.length
  const yBar = (v: number) => top + plotH - (v / maxBar) * plotH
  const yLine = (v: number) => top + plotH - (v / maxLine) * plotH
  const cx = (i: number) => left + step * (i + 0.5)
  const groupW = Math.min(step * 0.7, 30)
  const barW = groupW / 3
  return {
    bars: rows.flatMap((r, i) => [
      { x: cx(i) - groupW / 2, y: yBar(r.org), w: barW, h: top + plotH - yBar(r.org), cls: 'trend-bar-org' },
      { x: cx(i) - groupW / 2 + barW, y: yBar(r.acc), w: barW, h: top + plotH - yBar(r.acc), cls: 'trend-bar-acc' },
      { x: cx(i) - groupW / 2 + barW * 2, y: yBar(r.agr), w: barW, h: top + plotH - yBar(r.agr), cls: 'trend-bar-agr' },
    ]),
    fundPts: rows.map((r, i) => `${cx(i)},${yLine(r.fund)}`).join(' '),
    grids: [0, 0.5, 1].map(f => ({ y: top + plotH - f * plotH, label: fmt(Math.round(maxBar * f)) })),
    months: rows.map((r, i) => ({ x: cx(i), label: r.month })),
  }
})

